import{_ as e,o as d,c as r,a2 as a}from"./chunks/framework.v1TqQkD7.js";const p=JSON.parse('{"title":"Phase 0 Audit","description":"","frontmatter":{"title":"Phase 0 Audit","sourceFile":"guides/AUDIT.md"},"headers":[],"relativePath":"guide/audit.md","filePath":"guide/audit.md"}'),o={name:"guide/audit.md"};function i(n,t,s,c,l,h){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="phase-0-audit" tabindex="-1">Phase 0 Audit <a class="header-anchor" href="#phase-0-audit" aria-label="Permalink to &quot;Phase 0 Audit&quot;">​</a></h1><p>A snapshot of ESI.ts at 10.2.3 (master, 2026-09-26), taken as Phase 0 of the &quot;Road to Done&quot; plan. It records what is hand-written, what is generated, which ESI operations the client covers, and the mutation baseline, so the later phases start from measured facts. Re-run the numbers rather than editing them by hand; the commands are listed with each table.</p><h2 id="code-inventory" tabindex="-1">Code inventory <a class="header-anchor" href="#code-inventory" aria-label="Permalink to &quot;Code inventory&quot;">​</a></h2><p>Line counts exclude <code>*.generated.ts</code>.</p><table tabindex="0"><thead><tr><th>Area</th><th style="text-align:right;">Files</th><th style="text-align:right;">Lines</th><th>Origin</th></tr></thead><tbody><tr><td><code>src/clients</code></td><td style="text-align:right;">40</td><td style="text-align:right;">4965</td><td>Hand-written: 39 domain clients plus <code>BaseEsiClient</code></td></tr><tr><td><code>src/core/endpoints</code></td><td style="text-align:right;">42</td><td style="text-align:right;">2501</td><td>Hand-written endpoint definitions (234 path and method entries)</td></tr><tr><td><code>src/core</code> (rest)</td><td style="text-align:right;">46</td><td style="text-align:right;">4909</td><td>Hand-written pipeline, cache, retry, rate limiter, pagination</td></tr><tr><td><code>src/schemas</code></td><td style="text-align:right;">39</td><td style="text-align:right;">2571</td><td>Hand-written Zod schemas, checked by <code>npm run schema:drift</code></td></tr><tr><td><code>src/types</code></td><td style="text-align:right;">40</td><td style="text-align:right;">1437</td><td>Hand-written response types, branded IDs</td></tr><tr><td><code>src/auth</code></td><td style="text-align:right;">9</td><td style="text-align:right;">1399</td><td>Hand-written SSO and token handling</td></tr><tr><td><code>src/sde</code></td><td style="text-align:right;">18</td><td style="text-align:right;">6289</td><td>Hand-written SDE ingestion and query (separate sub-path export)</td></tr><tr><td><code>src/config</code></td><td style="text-align:right;">4</td><td style="text-align:right;">88</td><td>Hand-written</td></tr><tr><td><code>src/testing</code></td><td style="text-align:right;">2</td><td style="text-align:right;">1054</td><td>Hand-written test helpers (public sub-path)</td></tr></tbody></table><p>Generated from the ESI spec at compatibility date 2026-05-19 (<code>npm run generate:types</code>):</p><table tabindex="0"><thead><tr><th>File</th><th style="text-align:right;">Lines</th><th>Holds</th></tr></thead><tbody><tr><td><code>src/types/generated/esi-spec.generated.ts</code></td><td style="text-align:right;">2383</td><td>Response interfaces</td></tr><tr><td><code>src/core/endpoints/esi-scopes.generated.ts</code></td><td style="text-align:right;">218</td><td><code>EsiScope</code> union (72), scope per endpoint</td></tr><tr><td><code>src/core/endpoints/esi-rate-limit-groups.generated.ts</code></td><td style="text-align:right;">168</td><td>Rate-limit group per endpoint (156)</td></tr><tr><td><code>src/core/endpoints/esi-cache-ttls.generated.ts</code></td><td style="text-align:right;">142</td><td>Cache TTL per endpoint (136)</td></tr></tbody></table><p>Today only types and per-route metadata are generated. Every operation is reached through a hand-written endpoint definition, client method and Zod schema, about 10,000 hand-written lines that Phase 1 would move to the generator.</p><h2 id="operation-coverage" tabindex="-1">Operation coverage <a class="header-anchor" href="#operation-coverage" aria-label="Permalink to &quot;Operation coverage&quot;">​</a></h2><p>Counted by matching <code>METHOD path</code> between the spec and every <code>src/core/endpoints/*Endpoints.ts</code> definition, with path parameters normalised.</p><table tabindex="0"><thead><tr><th>Source</th><th style="text-align:right;">Operations</th></tr></thead><tbody><tr><td>Vendored spec <code>tests/contract/snapshots/esi-openapi.snapshot.json</code></td><td style="text-align:right;">218</td></tr><tr><td>of which require auth</td><td style="text-align:right;">137</td></tr><tr><td>of which take a page or cursor parameter</td><td style="text-align:right;">45</td></tr><tr><td>Endpoint definitions in <code>src/core/endpoints</code></td><td style="text-align:right;">234</td></tr></tbody></table><p>Findings, re-checked on 2026-09-26 after Phase 1 re-vendored the spec at 2026-05-19 (the date the client sends) through <code>.github/workflows/spec-refresh.yml</code>:</p><ol><li><strong>Resolved: the vendored spec now matches the date the client sends.</strong> It was pinned to 2025-12-16 (208 operations); <code>scripts/spec/snapshot-openapi.ts</code> now defaults to <code>COMPATIBILITY_DATE</code>. <code>npm run spec:coverage</code> checks the generated operations against it in CI.</li><li><strong>Every spec operation has a definition.</strong> <code>GET /sovereignty/map</code> and <code>GET /sovereignty/structures</code>, missing before, are covered at 2026-05-19.</li><li><strong>16 definitions are not in the spec at 2026-05-19, all intentional.</strong> SKINR cosmetics (3), Paragon Hub (5) and military campaigns (6) are beta routes ESI enabled after that compatibility date (<a href="https://developers.eveonline.com/blog/skinr-on-esi-color-outside-the-lines" target="_blank" rel="noreferrer">SKINR on ESI</a>); the client supports them on purpose. <code>/meta/openapi.json</code> and <code>/meta/name</code> are meta routes outside the spec. Phase 2 has to keep these reachable even though the generator, which reads the vendored spec, does not emit them.</li><li>No operation in the vendored spec is marked <code>deprecated</code>.</li></ol><h2 id="mutation-baseline" tabindex="-1">Mutation baseline <a class="header-anchor" href="#mutation-baseline" aria-label="Permalink to &quot;Mutation baseline&quot;">​</a></h2><p>Per-directory floors enforced by the nightly ratchet (<code>scripts/mutation/mutation-ratchet.ts</code>). Stryker&#39;s global <code>break</code> is <code>null</code>; the gate is per directory. A dash means the file sets no floor for that directory.</p><table tabindex="0"><thead><tr><th>Directory</th><th style="text-align:right;">Unit (<code>config/mutation/unit-thresholds.json</code>)</th><th style="text-align:right;">BDD-only (<code>config/mutation/bdd-thresholds.json</code>)</th></tr></thead><tbody><tr><td><code>src</code></td><td style="text-align:right;">—</td><td style="text-align:right;">15.5</td></tr><tr><td><code>src/auth</code></td><td style="text-align:right;">—</td><td style="text-align:right;">23.4</td></tr><tr><td><code>src/clients</code></td><td style="text-align:right;">—</td><td style="text-align:right;">12.1</td></tr><tr><td><code>src/core</code></td><td style="text-align:right;">81.8</td><td style="text-align:right;">28.8</td></tr><tr><td><code>src/core/cache</code></td><td style="text-align:right;">65.3</td><td style="text-align:right;">22.3</td></tr><tr><td><code>src/core/circuitBreaker</code></td><td style="text-align:right;">77.7</td><td style="text-align:right;">37.3</td></tr><tr><td><code>src/core/endpoints</code></td><td style="text-align:right;">—</td><td style="text-align:right;">24.5</td></tr><tr><td><code>src/core/logger</code></td><td style="text-align:right;">55.5</td><td style="text-align:right;">21.7</td></tr><tr><td><code>src/core/middleware</code></td><td style="text-align:right;">100.0</td><td style="text-align:right;">26.0</td></tr><tr><td><code>src/core/pagination</code></td><td style="text-align:right;">73.9</td><td style="text-align:right;">12.6</td></tr><tr><td><code>src/core/rateLimiter</code></td><td style="text-align:right;">77.9</td><td style="text-align:right;">11.7</td></tr><tr><td><code>src/core/requestPipeline</code></td><td style="text-align:right;">75.2</td><td style="text-align:right;">38.5</td></tr><tr><td><code>src/core/util</code></td><td style="text-align:right;">95.4</td><td style="text-align:right;">42.8</td></tr><tr><td><code>src/schemas</code></td><td style="text-align:right;">—</td><td style="text-align:right;">0.0</td></tr><tr><td><code>src/sde</code></td><td style="text-align:right;">—</td><td style="text-align:right;">10.6</td></tr></tbody></table><p>The plan&#39;s target is 90 on the hand-written core and 80 repo-wide. Only <code>src/core/middleware</code> and <code>src/core/util</code> meet 90 today; <code>src/core/logger</code> (55.5) and <code>src/core/cache</code> (65.3) are furthest away.</p><h2 id="plan-gates-today" tabindex="-1">Plan gates today <a class="header-anchor" href="#plan-gates-today" aria-label="Permalink to &quot;Plan gates today&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gate</th><th>State</th><th>Evidence and gap</th></tr></thead><tbody><tr><td>Route coverage</td><td>Partial</td><td><code>spec:coverage</code> checks every spec operation has a generated function; mapping them onto client scopes is Phase 2</td></tr><tr><td>Spec drift</td><td>Partial</td><td><code>nightly-spec-drift.yml</code> and <code>schema:drift</code> exist; the vendored snapshot is at the sent date and <code>spec-refresh.yml</code> re-vendors it</td></tr><tr><td>Public API</td><td>Met</td><td><code>etc/esi.ts.api.md</code> committed, API Surface Check and API SemVer Gate in CI</td></tr><tr><td>Type safety</td><td>Partial</td><td><code>strict</code> and <code>noUncheckedIndexedAccess</code> on; <code>exactOptionalPropertyTypes</code> on (11.0); <code>isolatedDeclarations</code> checked over the pipeline, ports, generated code, client, auth and entry points (<code>typecheck:isolated</code>), not the Zod schemas or endpoint maps, whose types are inferred by design (ROADMAP Phase 3); tsd type tests exist</td></tr><tr><td>Tests</td><td>Partial</td><td>Unit, BDD, contract replay, fuzz, faults and consumer tiers all run; mutation floors below the plan&#39;s 90/80</td></tr><tr><td>Security</td><td>Partial</td><td>Provenance on publish, CodeQL, Scorecard, zizmor, SHA-pinned actions; publishing still uses <code>NPM_TOKEN</code>, not trusted publishing; <code>pino</code> and <code>zod</code> are runtime deps</td></tr><tr><td>Package health</td><td>Partial</td><td>publint, attw, size budgets and the consumer matrix run; <code>engines.node</code> is <code>&gt;=18</code>; no <code>sideEffects</code> field; no Bun, Deno or browser matrix</td></tr><tr><td>Docs</td><td>Partial</td><td>README and guide examples are type-checked; the VitePress site in <code>docs-site/</code> is not deployed (esi-06b)</td></tr><tr><td>Release</td><td>Partial</td><td>release-please, commitlint and the SBOM script exist; the release pipeline has open P1 defects (esi-l38.5)</td></tr><tr><td>Live health</td><td>Not met</td><td>Nightly recorded-payload and Schemathesis jobs exist, but there is no nightly smoke against Tranquility with an authenticated route</td></tr></tbody></table><h2 id="transport-rules-from-the-plan" tabindex="-1">Transport rules from the plan <a class="header-anchor" href="#transport-rules-from-the-plan" aria-label="Permalink to &quot;Transport rules from the plan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>State</th></tr></thead><tbody><tr><td>Send <code>X-Compatibility-Date</code> on every request</td><td>Done (<code>src/core/requestPipeline/headers.ts</code>)</td></tr><tr><td>Send <code>X-Tenant</code></td><td>Missing: no request sets it</td></tr><tr><td>Descriptive <code>User-Agent</code>, refuse to build without one</td><td>Partial: <code>X-User-Agent</code> carries <code>clientId</code>, which defaults to <code>esi-client</code> and is never required</td></tr><tr><td>ETag, <code>If-None-Match</code>, 304 as a hit</td><td>Done (spec-aware TTL cache)</td></tr><tr><td><code>X-Pages</code> pagination</td><td>Done (offset and cursor handlers); open defect esi-l38.1</td></tr><tr><td>Error-limit tracking</td><td>Done (<code>src/core/rateLimiter/RateLimiter.ts</code>)</td></tr><tr><td>Surface <code>Warning</code> headers</td><td>Done as warn logs; not yet a typed event</td></tr></tbody></table>',21)])])}const y=e(o,[["render",i]]);export{p as __pageData,y as default};
